/// <summary>
/// The <c>METInventOnhandItemInstrumentationActivities</c> class provides activities for <c>InventOnhandItem</c> form.
/// </summary>
internal final class METInventOnhandItemInstrumentationActivities
{
    private const str ActivityNamePrefix = 'InventOnhandItem.';
    private METInventInstrumentationLogger logger; 

}

Method.Source:
/// <summary>
/// new constructor for <c>METInventOnhandItemInstrumentationActivities</c> class.
/// </summary>
/// <param name = "_logger">METInventInstrumentationLogger</param>
private void new(METInventInstrumentationLogger _logger)
{
    logger = _logger;
}

/// <summary>
/// /// Creates a new instance of <c>METInventOnhandItemInstrumentationActivities</c> from the provided logger.
/// </summary>
/// <param name = "_logger">METInventInstrumentationLogger</param>
/// <returns>METInventOnhandItemInstrumentationActivities</returns>
public static METInventOnhandItemInstrumentationActivities newFromLogger(METInventInstrumentationLogger _logger)
{
    return new METInventOnhandItemInstrumentationActivities(_logger);
}

/// <summary>
/// /// Creates a SysInstrumentationActivityContext for the executeQuery activity of the InventOnhandItem form.
/// </summary>
/// <returns>SysInstrumentationActivityContext</returns>
public SysInstrumentationActivityContext inventSumExecuteQuery()
{
    SysInstrumentationActivity activity = logger.activity(ActivityNamePrefix + 'inventSum.executeQuery');
    return logger.activityContext(activity);
}

